//! .env file parsing.
//!
//! This module provides functionality for parsing environment variable files
//! in the standard KEY=value format.

use anyhow::Result;
use std::collections::HashMap;
use std::path::Path;

/// Parses .env files into a map of environment variables.
///
/// # Supported Formats
///
/// - Simple: `KEY=value`
/// - Quoted: `KEY="value with spaces"` or `KEY='single quoted'`
/// - Empty: `KEY=`
/// - Comments: `# This is a comment`
/// - Inline comments: `KEY=value # comment` (stripped for unquoted values)
/// - Whitespace around equals: `KEY = value`
/// - Values with equals signs: `URL=https://example.com?foo=bar`
/// - Export prefix: `export KEY=value`
/// - Escape sequences in double quotes: `\"`, `\\`, `\n`, `\t`, `\r`
/// - Single quotes are literal (no escape processing)
///
/// # Example
///
/// ```
/// use bivvy::config::EnvFileParser;
///
/// let content = r#"
/// # Database config
/// DATABASE_URL=postgres://localhost/db
/// DEBUG="true"
/// EMPTY=
/// "#;
///
/// let vars = EnvFileParser::parse(content).unwrap();
/// assert_eq!(vars.get("DATABASE_URL"), Some(&"postgres://localhost/db".to_string()));
/// assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
/// assert_eq!(vars.get("EMPTY"), Some(&"".to_string()));
/// ```
pub struct EnvFileParser;

impl EnvFileParser {
    /// Parse an env file content string into a map of variables.
    pub fn parse(content: &str) -> Result<HashMap<String, String>> {
        let mut vars = HashMap::new();

        for line in content.lines() {
            let line = line.trim();

            // Skip empty lines and comments
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            // Parse KEY=value
            if let Some((key, value)) = Self::parse_line(line) {
                vars.insert(key, value);
            }
        }

        Ok(vars)
    }

    /// Parse a single line, stripping an optional `export` prefix.
    fn parse_line(line: &str) -> Option<(String, String)> {
        let line = line
            .strip_prefix("export ")
            .or_else(|| line.strip_prefix("export\t"))
            .unwrap_or(line);

        let eq_pos = line.find('=')?;
        let key = line[..eq_pos].trim().to_string();
        let raw_value = line[eq_pos + 1..].trim();

        let value = Self::parse_value(raw_value);

        Some((key, value))
    }

    /// Parse a value, handling quotes, escape sequences, and inline comments.
    fn parse_value(value: &str) -> String {
        if value.starts_with('"') && Self::has_closing_double_quote(value) {
            Self::parse_double_quoted(value)
        } else if value.starts_with('\'') && value.len() >= 2 && value[1..].contains('\'') {
            Self::parse_single_quoted(value)
        } else {
            Self::strip_inline_comment(value)
        }
    }

    /// Check whether a double-quoted value has a valid closing quote,
    /// accounting for escaped quotes.
    fn has_closing_double_quote(value: &str) -> bool {
        let mut chars = value[1..].chars();
        while let Some(ch) = chars.next() {
            match ch {
                '\\' => {
                    chars.next(); // skip escaped char
                }
                '"' => return true,
                _ => {}
            }
        }
        false
    }

    /// Parse a double-quoted value with escape sequence processing.
    ///
    /// Supports `\"`, `\\`, `\n`, `\t`, and `\r`. Other `\X` sequences
    /// are preserved as-is.
    fn parse_double_quoted(value: &str) -> String {
        // Find the closing double quote, respecting escaped quotes
        let inner = &value[1..]; // skip opening quote
        let mut result = String::new();
        let mut chars = inner.chars();

        while let Some(ch) = chars.next() {
            match ch {
                '"' => break, // closing quote
                '\\' => match chars.next() {
                    Some('n') => result.push('\n'),
                    Some('t') => result.push('\t'),
                    Some('r') => result.push('\r'),
                    Some('\\') => result.push('\\'),
                    Some('"') => result.push('"'),
                    Some(other) => {
                        result.push('\\');
                        result.push(other);
                    }
                    None => result.push('\\'),
                },
                _ => result.push(ch),
            }
        }

        result
    }

    /// Parse a single-quoted value. No escape processing — content is literal.
    fn parse_single_quoted(value: &str) -> String {
        let inner = &value[1..]; // skip opening quote
        match inner.rfind('\'') {
            Some(pos) if pos > 0 || inner.starts_with('\'') => inner[..pos].to_string(),
            _ => inner.to_string(),
        }
    }

    /// Strip an inline comment (` # ...`) from an unquoted value.
    fn strip_inline_comment(value: &str) -> String {
        match value.find(" #") {
            Some(pos) => value[..pos].trim_end().to_string(),
            None => value.to_string(),
        }
    }

    /// Load and parse an env file from a path.
    ///
    /// # Example
    ///
    /// ```no_run
    /// use bivvy::config::EnvFileParser;
    /// use std::path::Path;
    ///
    /// let vars = EnvFileParser::load(Path::new(".env")).unwrap();
    /// for (key, value) in &vars {
    ///     println!("{}={}", key, value);
    /// }
    /// ```
    pub fn load(path: &Path) -> Result<HashMap<String, String>> {
        let content = std::fs::read_to_string(path)?;
        Self::parse(&content)
    }

    /// Load and parse an env file, returning empty map if file doesn't exist.
    pub fn load_optional(path: &Path) -> Result<HashMap<String, String>> {
        if path.exists() {
            Self::load(path)
        } else {
            Ok(HashMap::new())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_simple_env_file() {
        let content = r#"
KEY1=value1
KEY2=value2
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY1"), Some(&"value1".to_string()));
        assert_eq!(vars.get("KEY2"), Some(&"value2".to_string()));
    }

    #[test]
    fn skips_comments() {
        let content = r#"
# This is a comment
KEY=value
# Another comment
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 1);
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn handles_quoted_values() {
        let content = r#"
DOUBLE="double quoted"
SINGLE='single quoted'
UNQUOTED=no quotes
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("DOUBLE"), Some(&"double quoted".to_string()));
        assert_eq!(vars.get("SINGLE"), Some(&"single quoted".to_string()));
        assert_eq!(vars.get("UNQUOTED"), Some(&"no quotes".to_string()));
    }

    #[test]
    fn handles_empty_values() {
        let content = "EMPTY=";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("EMPTY"), Some(&"".to_string()));
    }

    #[test]
    fn handles_values_with_equals() {
        let content = "URL=https://example.com?foo=bar";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(
            vars.get("URL"),
            Some(&"https://example.com?foo=bar".to_string())
        );
    }

    #[test]
    fn handles_whitespace_around_equals() {
        let content = "KEY = value with spaces";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY"), Some(&"value with spaces".to_string()));
    }

    #[test]
    fn skips_empty_lines() {
        let content = r#"
KEY1=value1

KEY2=value2

"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn handles_lines_without_equals() {
        let content = r#"
KEY1=value1
invalid line without equals
KEY2=value2
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn load_optional_returns_empty_for_missing_file() {
        let result = EnvFileParser::load_optional(Path::new("/nonexistent/path/.env"));

        assert!(result.is_ok());
        assert!(result.unwrap().is_empty());
    }

    #[test]
    fn empty_quoted_values() {
        let content = "DOUBLE=\"\"\nSINGLE=''";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("DOUBLE"), Some(&"".to_string()));
        assert_eq!(vars.get("SINGLE"), Some(&"".to_string()));
    }

    #[test]
    fn escaped_double_quotes_in_double_quoted_value() {
        let content = r#"KEY="say \"hello\" world""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"say \"hello\" world".to_string()));
    }

    #[test]
    fn escaped_backslash_in_double_quoted_value() {
        let content = r#"PATH="C:\\Users\\name""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("PATH"), Some(&"C:\\Users\\name".to_string()));
    }

    #[test]
    fn escaped_newline_in_double_quoted_value() {
        let content = "KEY=\"line1\\nline2\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"line1\nline2".to_string()));
    }

    #[test]
    fn single_quotes_preserve_backslashes_literally() {
        let content = r"KEY='no \n escaping \\ here'";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&r"no \n escaping \\ here".to_string())
        );
    }

    #[test]
    fn single_quotes_preserve_escaped_quote_literally() {
        let content = r#"KEY='hello \" world'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"hello \" world"#.to_string()));
    }

    #[test]
    fn inline_comment_stripped_from_unquoted_value() {
        let content = "KEY=value # this is a comment";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn hash_preserved_in_double_quoted_value() {
        let content = "KEY=\"value # not a comment\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # not a comment".to_string())
        );
    }

    #[test]
    fn hash_preserved_in_single_quoted_value() {
        let content = "KEY='value # not a comment'";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # not a comment".to_string())
        );
    }

    #[test]
    fn mismatched_quotes_treated_as_unquoted() {
        let content = "KEY=\"mismatched'";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"\"mismatched'".to_string()));
    }

    #[test]
    fn whitespace_preserved_inside_double_quotes() {
        let content = "KEY=\"  spaces  \"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaces  ".to_string()));
    }

    #[test]
    fn whitespace_preserved_inside_single_quotes() {
        let content = "KEY='  spaces  '";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaces  ".to_string()));
    }

    #[test]
    fn export_prefix_handled() {
        let content = "export KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn export_prefix_with_quotes() {
        let content = "export KEY=\"quoted value\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"quoted value".to_string()));
    }

    #[test]
    fn escaped_tab_in_double_quoted_value() {
        let content = "KEY=\"col1\\tcol2\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"col1\tcol2".to_string()));
    }

    #[test]
    fn quote_in_middle_of_unquoted_value() {
        let content = "KEY=he\"llo";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"he\"llo".to_string()));
    }

    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }
}

